import mongoose from 'mongoose';

const dailyUsageSchema = new mongoose.Schema(
  {
    creator: {
      type: String,
      required: true,
    },

    // UTC date, generated by our server—not supplied by the browser.
    day: {
      type: String,
      required: true,
      match: /^\d{4}-\d{2}-\d{2}$/,
    },

    courses: {
      type: Number,
      required: true,
      default: 0,
      min: 0,
      validate: Number.isInteger,
    },
    courseAttempts: {
      type: Number,
      required: true,
      default: 0,
      min: 0,
      validate: Number.isInteger,
    },
    courseReservationIds: {
      type: [String],
      default: [],
    },

    audio: {
      type: Number,
      required: true,
      default: 0,
      min: 0,
      validate: Number.isInteger,
    },

    lessons: {
      type: Number,
      required: true,
      default: 0,
      min: 0,
      validate: Number.isInteger,
    },
  },
  {
    timestamps: true,
  },
);

dailyUsageSchema.index(
  { creator: 1, day: 1 },
  { unique: true },
);

export default mongoose.model('DailyUsage', dailyUsageSchema);
